// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address nonOwner, uint256 value, bytes memory data) public {
        vm.assume(nonOwner != c.owner());
        bound(value, 0, address(c).balance);
        vm.assume(data.length <= 1024);

        bool ok;
        vm.prank(nonOwner);
        try c.sendMoney(nonOwner, value, data) {
            ok = true;
        } catch {
            ok = false;
        }

        assertFalse(ok);
    }
}
